struct RECT { long left, top, right, bottom; };

RECT exposedAfterScroll(RECT client, int dy) { return { 0, 0, 0, 0 }; }
void rowsToPaint(RECT paint, int scrollY, int rowHeight, int rowCount, int& first, int& last) { first = 0; last = -1; }

class BackBuffer
{
public:
    bool ensure(int width, int height) { return false; }
    int width() const { return 0; }
    int height() const { return 0; }
};

solution.solution.cpp:
#include <algorithm>
#include <cstdlib>

struct RECT { long left, top, right, bottom; };

RECT exposedAfterScroll(RECT client, int dy)
{
    if (dy == 0) return { 0, 0, 0, 0 };
    const long height{ client.bottom - client.top };
    if (std::labs(dy) >= height) return client;
    if (dy < 0) return { client.left, client.bottom + dy, client.right, client.bottom };
    return { client.left, client.top, client.right, client.top + dy };
}

void rowsToPaint(RECT paint, int scrollY, int rowHeight, int rowCount, int& first, int& last)
{
    first = 0;
    last = -1;
    if (rowCount <= 0 || paint.bottom <= paint.top) return;
    const long top{ paint.top + scrollY }, bottom{ paint.bottom + scrollY };     // document coordinates, bottom exclusive
    if (bottom <= 0) return;
    const long f{ std::max(0L, top) / rowHeight };
    const long l{ (bottom - 1) / rowHeight };
    if (f > rowCount - 1) return;
    first = static_cast<int>(f);
    last = static_cast<int>(std::min<long>(l, rowCount - 1));
}

class BackBuffer
{
public:
    bool ensure(int width, int height)
    {
        if (width <= m_w && height <= m_h) return false;
        auto up = [](int v) { return (v + 255) / 256 * 256; };
        m_w = std::max(m_w, up(width));
        m_h = std::max(m_h, up(height));
        return true;
    }

    int width() const { return m_w; }
    int height() const { return m_h; }

private:
    int m_w{ 0 }, m_h{ 0 };
};

unitTests:
bool same(RECT r, long l, long t, long rr, long b) { return r.left == l && r.top == t && r.right == rr && r.bottom == b; }
TEST("scrolling exposes a strip") {
    const RECT c{ 0, 0, 640, 480 };
    CHECK(same(exposedAfterScroll(c, -40), 0, 440, 640, 480)); CHECK(same(exposedAfterScroll(c, 25), 0, 0, 640, 25));
    CHECK(same(exposedAfterScroll(c, -480), 0, 0, 640, 480)); CHECK(same(exposedAfterScroll(c, 0), 0, 0, 0, 0));
}
TEST("rows to paint") {
    int f = 0, l = 0;
    rowsToPaint({ 0, 0, 640, 480 }, 0, 20, 1000, f, l); CHECK_EQ(f, 0); CHECK_EQ(l, 23);
    rowsToPaint({ 0, 440, 640, 480 }, 1000, 20, 1000, f, l); CHECK_EQ(f, 72); CHECK_EQ(l, 73);
    rowsToPaint({ 0, 0, 640, 480 }, 19950, 20, 1000, f, l); CHECK_EQ(f, 997); CHECK_EQ(l, 999);
    rowsToPaint({ 0, 0, 640, 480 }, 30000, 20, 1000, f, l); CHECK_EQ(f, 0); CHECK_EQ(l, -1);
    rowsToPaint({ 0, 10, 640, 11 }, 0, 20, 5, f, l); CHECK_EQ(f, 0); CHECK_EQ(l, 0);
}
TEST("the back buffer grows, never shrinks") {
    BackBuffer b; CHECK(b.ensure(800, 600)); CHECK_EQ(b.width(), 1024); CHECK_EQ(b.height(), 768);
    CHECK(!b.ensure(1000, 700)); CHECK(!b.ensure(300, 200)); CHECK(b.ensure(1025, 100)); CHECK_EQ(b.width(), 1280); CHECK_EQ(b.height(), 768);
}

